cd /Users/guygouri/Devlab/ernlang/ern && S=/private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad; mkdir -p $S/p7ver_gq; cat > $S/p7ver_gq/defs.py <<'EOF'
import re,sys
def blocks(path):
    src=open(path).read().split('\n'); d={}; cur=None
    kw=re.compile(r'^(?:@\[[^\]]*\]\s*)?(?:private |protected |noncomputable )?(def|abbrev|structure|inductive|theorem|lemma|instance|example|class)\s+(\S*)')
    for i,l in enumerate(src):
        m=kw.match(l)
        if m or l.startswith('/--') or l.startswith('section') or l.startswith('end ') or l.startswith('namespace') or l.startswith('--'):
            cur=None
        if m and m.group(1) in ('def','abbrev','structure','inductive','class'):
            cur=m.group(2); d[cur]=[]
        if cur is not None: d[cur].append(l)
    return {k:'\n'.join(v).rstrip() for k,v in d.items()}
a=blocks(sys.argv[1]); b=blocks(sys.argv[2])
print('removed',[k for k in a if k not in b])
print('added',[k for k in b if k not in a])
for k in a:
    if k in b and re.sub(r'\s+',' ',a[k])!=re.sub(r'\s+',' ',b[k]): print('CHANGED',k)
EOF
